const TRAIL_HTML   = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Heritage Trail \u2014 Clarens Heritage Association</title>\n<meta name=\"description\" content=\"Walk Clarens with the full story in your pocket. 32+ heritage sites, exclusive partner vouchers, and a digital passport. Try 5 sites free, unlock all for R99. Launching 19 June 2026.\">\n<link rel=\"icon\" href=\"https://clarensheritage.org/wp-content/uploads/2024/10/cropped-Favicon-1-270x270.jpg\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;0,700;1,400&family=Lato:wght@300;400;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --olive:#4a5234;--olive-dark:#3a4028;--olive-deep:#2b3022;\n  --sage:#c8d4b8;--sage-soft:#dde6cf;--cream:#faf4e8;--sand:#f0e3cd;\n  --gold:#c8a052;--amber:#e0a23f;--coral:#e0703c;--coral-deep:#c2542a;\n  --blue:#1a4a7a;--blue-soft:#3d6fa0;--ink:#2b2a26;--paper:#fffdf8;\n  --shadow:rgba(74,82,52,.2);\n  --display:'Cormorant Garamond',Georgia,serif;\n  --body:'Lato',-apple-system,system-ui,sans-serif;\n}\n*{margin:0;padding:0;box-sizing:border-box}\nhtml{scroll-behavior:smooth;-webkit-text-size-adjust:100%}\nbody{font-family:var(--body);color:var(--ink);background:var(--cream);line-height:1.7;overflow-x:hidden}\nimg{max-width:100%;display:block}\na{color:inherit;text-decoration:none}\n\n/* \u2500\u2500 NAV (matches CHA site exactly) \u2500\u2500 */\n.cha-nav{\n  position:fixed;top:0;left:0;right:0;z-index:1000;\n  background:var(--olive);\n}\n.cha-nav-inner{\n  max-width:1440px;margin:0 auto;\n  display:flex;align-items:center;justify-content:space-between;\n  padding:16px clamp(20px,5vw,60px);\n}\n.cha-brand{display:flex;align-items:center}\n.cha-logo{height:54px;width:auto;filter:brightness(0) invert(1)}\n.cha-logo-mobile{height:44px;width:auto;display:none;filter:brightness(0) invert(1)}\n.cha-nav-links{\n  list-style:none;display:flex;align-items:center;gap:28px;\n}\n.cha-nav-links>li{position:relative}\n.cha-nav-links a{\n  color:rgba(255,255,255,.88);\n  font-family:var(--display);font-size:1.02rem;letter-spacing:.04em;\n  transition:color .2s;white-space:nowrap;\n}\n.cha-nav-links a:hover,.cha-nav-links a.active{color:#fff}\n.cha-nav-links .arrow{font-size:.7rem;margin-left:3px}\n.cha-dropdown{\n  position:absolute;top:calc(100% + 12px);left:0;\n  background:var(--olive);min-width:164px;\n  display:none;box-shadow:0 10px 28px rgba(0,0,0,.25);\n  border-top:2px solid rgba(255,255,255,.15);\n}\n.cha-nav-links li:hover .cha-dropdown{display:block}\n.cha-dropdown li a{display:block;padding:10px 20px;font-size:.96rem}\n.cha-social{display:flex;gap:8px;margin-left:14px}\n.cha-social a{\n  color:#fff;width:30px;height:30px;border-radius:50%;\n  border:1.5px solid rgba(255,255,255,.55);\n  display:grid;place-items:center;font-size:.8rem;transition:.2s;\n}\n.cha-social a:hover{border-color:#fff;background:rgba(255,255,255,.12)}\n.burger{\n  display:none;flex-direction:column;gap:5px;cursor:pointer;\n  padding:6px;background:none;border:0;margin-left:10px;\n}\n.burger span{width:26px;height:2px;background:#fff;border-radius:1px;transition:.3s}\n\n/* \u2500\u2500 HERO \u2500\u2500 */\n.hero{\n  position:relative;min-height:100vh;display:flex;flex-direction:column;\n  justify-content:flex-end;overflow:hidden;\n  background:var(--olive);padding-top:88px;\n}\n.hero-photo{\n  position:absolute;inset:0;width:100%;height:100%;\n  object-fit:cover;object-position:center 38%;z-index:0;\n  animation:kenburns 26s ease-in-out infinite alternate;\n}\n@keyframes kenburns{from{transform:scale(1.04)}to{transform:scale(1.13) translateY(-1%)}}\n.hero-scrim{\n  position:absolute;inset:0;z-index:1;\n  background:linear-gradient(180deg,\n    rgba(74,82,52,.58) 0%,\n    rgba(74,82,52,.25) 28%,\n    rgba(43,48,34,.52) 65%,\n    rgba(43,48,34,.94) 100%);\n}\n.hero-inner{\n  position:relative;z-index:5;\n  padding:0 clamp(20px,6vw,64px) clamp(52px,9vh,100px);\n  max-width:1180px;margin:0 auto;width:100%;\n}\n.hero-badge{\n  display:inline-block;\n  border:1.5px solid rgba(255,255,255,.6);\n  color:rgba(255,255,255,.9);\n  font-family:var(--body);font-weight:700;font-size:.7rem;\n  letter-spacing:.18em;text-transform:uppercase;\n  padding:7px 18px;border-radius:40px;margin-bottom:20px;\n}\nh1.hero-title{\n  font-family:var(--display);color:#fff;font-weight:400;\n  font-size:clamp(3rem,9vw,6.5rem);line-height:1;letter-spacing:.01em;\n  text-shadow:0 4px 30px rgba(30,20,8,.4);margin-bottom:20px;\n}\n.hero-sub{\n  color:rgba(255,255,255,.92);font-size:clamp(1rem,2vw,1.3rem);\n  max-width:620px;margin-bottom:8px;font-weight:300;line-height:1.7;\n}\n.hero-sub b{font-weight:700;color:#fff}\n.hero-stats{display:flex;flex-wrap:wrap;gap:28px;margin:22px 0 34px}\n.hero-stats div{color:#fff}\n.hero-stats b{\n  font-family:var(--display);font-size:2rem;font-weight:600;\n  display:block;line-height:1;\n}\n.hero-stats span{font-size:.72rem;font-weight:700;letter-spacing:.14em;text-transform:uppercase;opacity:.85}\n.cta-row{display:flex;flex-wrap:wrap;gap:14px;align-items:center}\n.btn-cha{\n  display:inline-block;background:#fff;color:var(--olive-dark);\n  padding:16px 44px;\n  font-family:var(--body);font-weight:700;font-size:.76rem;\n  letter-spacing:.18em;text-transform:uppercase;\n  transition:background .2s,color .2s,transform .2s;\n}\n.btn-cha:hover{background:rgba(255,255,255,.9);transform:translateY(-2px)}\n.btn-cha.btn-locked{background:rgba(255,255,255,.35);color:rgba(255,255,255,.7);cursor:default;pointer-events:none}\n.btn-cha.btn-locked:hover{transform:none;background:rgba(255,255,255,.35)}\n.btn-cha-ghost{\n  display:inline-block;\n  border:1.5px solid rgba(255,255,255,.65);color:rgba(255,255,255,.92);\n  padding:16px 36px;\n  font-family:var(--body);font-weight:700;font-size:.76rem;\n  letter-spacing:.18em;text-transform:uppercase;\n  transition:border-color .2s,color .2s,transform .2s;\n}\n.btn-cha-ghost:hover{border-color:#fff;color:#fff;transform:translateY(-2px)}\n\n/* countdown */\n.countdown-wrap{margin-bottom:22px}\n.launch-pill{\n  display:inline-block;\n  background:linear-gradient(135deg,var(--gold),var(--coral));color:#fff;\n  font-weight:700;font-size:.7rem;letter-spacing:.14em;text-transform:uppercase;\n  padding:8px 18px;border-radius:40px;\n  box-shadow:0 6px 18px rgba(200,90,50,.4);\n}\n.countdown{display:flex;gap:8px;margin-top:12px}\n.countdown div{\n  background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.25);\n  backdrop-filter:blur(4px);border-radius:10px;\n  padding:8px 12px;text-align:center;min-width:54px;\n}\n.countdown b{font-family:var(--display);font-size:1.4rem;font-weight:600;color:#fff;display:block;line-height:1}\n.countdown span{font-size:.58rem;letter-spacing:.12em;text-transform:uppercase;color:rgba(255,255,255,.78)}\n.credit{position:absolute;right:12px;bottom:10px;z-index:6;font-size:.62rem;color:rgba(255,255,255,.5)}\n.credit a{border-bottom:1px dotted rgba(255,255,255,.4)}.credit a:hover{color:#fff}\n\n/* scroll hint */\n.scroll-hint{position:absolute;left:50%;bottom:16px;transform:translateX(-50%);z-index:6;color:rgba(255,255,255,.65);font-size:.64rem;letter-spacing:.2em;text-transform:uppercase;text-align:center;animation:bob 2.2s ease-in-out infinite}\n.scroll-hint span{display:block;font-size:1.1rem;margin-top:2px}\n@keyframes bob{0%,100%{transform:translate(-50%,0)}50%{transform:translate(-50%,6px)}}\n\n/* fade animations */\n.fade-up{opacity:0;transform:translateY(26px)}\n.hero .fade-up{animation:up .9s cubic-bezier(.2,.8,.2,1) forwards}\n.hero .d1{animation-delay:.1s}.hero .d2{animation-delay:.25s}.hero .d3{animation-delay:.4s}.hero .d4{animation-delay:.55s}.hero .d5{animation-delay:.7s}\n@keyframes up{to{opacity:1;transform:translateY(0)}}\n.reveal{opacity:0;transform:translateY(36px);transition:opacity .7s ease,transform .7s cubic-bezier(.2,.8,.2,1)}\n.reveal.in{opacity:1;transform:none}\n.reveal.in.s1{transition-delay:.07s}.reveal.in.s2{transition-delay:.14s}.reveal.in.s3{transition-delay:.21s}.reveal.in.s4{transition-delay:.28s}\n\n/* \u2500\u2500 SECTIONS \u2500\u2500 */\nsection{position:relative}\n.wrap{max-width:1180px;margin:0 auto;padding:clamp(60px,9vw,112px) clamp(20px,6vw,64px)}\n.tag{display:inline-block;font-weight:700;font-size:.68rem;letter-spacing:.18em;text-transform:uppercase;padding:7px 15px;border-radius:40px;margin-bottom:16px}\n.tag-gold{background:rgba(200,160,82,.18);color:#9c7420}\n.tag-blue{background:rgba(26,74,122,.12);color:var(--blue)}\n.tag-coral{background:rgba(224,112,60,.16);color:var(--coral-deep)}\nh2{font-family:var(--display);font-weight:400;font-size:clamp(2rem,5vw,3.2rem);line-height:1.1;letter-spacing:.01em;color:var(--olive-dark)}\nh2 em{font-style:italic;color:var(--coral-deep)}\n.lead{font-size:clamp(1rem,2vw,1.2rem);color:#5a5c4e;max-width:640px;margin-top:14px;font-weight:300;line-height:1.8}\n.center{text-align:center}.center .lead{margin-left:auto;margin-right:auto}\n\n/* \u2500\u2500 MODEL \u2500\u2500 */\n.model{background:var(--paper)}\n.flow{display:grid;grid-template-columns:repeat(3,1fr);gap:0;margin-top:50px;position:relative}\n.fstep{position:relative;padding:0 22px;text-align:center}\n.fstep:not(:last-child)::after{content:\"\u2192\";position:absolute;right:-12px;top:28px;font-size:1.5rem;color:var(--gold);font-weight:400;font-family:var(--display)}\n.fstep .circle{width:72px;height:72px;border-radius:50%;margin:0 auto 16px;display:grid;place-items:center;font-size:1.8rem;color:#fff}\n.fstep:nth-child(1) .circle{background:linear-gradient(135deg,var(--olive),#5e6a48)}\n.fstep:nth-child(2) .circle{background:linear-gradient(135deg,var(--blue),var(--blue-soft))}\n.fstep:nth-child(3) .circle{background:linear-gradient(135deg,var(--gold),var(--coral))}\n.fstep h3{font-family:var(--display);font-size:1.3rem;font-weight:600;color:var(--olive-dark);margin-bottom:8px}\n.fstep p{font-size:.95rem;color:#5a5c4e;font-weight:300}\n.fstep .badge{display:inline-block;margin-top:10px;font-size:.68rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;padding:5px 12px;border-radius:30px}\n.fstep:nth-child(1) .badge{background:var(--sage-soft);color:var(--olive)}\n.fstep:nth-child(2) .badge{background:var(--sage-soft);color:var(--olive)}\n.fstep:nth-child(3) .badge{background:rgba(224,112,60,.16);color:var(--coral-deep)}\n\n/* \u2500\u2500 FEATURES \u2500\u2500 */\n.features{background:linear-gradient(180deg,var(--cream),var(--sand))}\n.feat-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(225px,1fr));gap:22px;margin-top:48px}\n.feat{padding:32px 26px;border-radius:4px;background:var(--paper);border:1px solid rgba(74,82,52,.1);transition:transform .3s,box-shadow .3s}\n.feat:hover{transform:translateY(-6px);box-shadow:0 20px 44px var(--shadow)}\n.feat .ic{width:56px;height:56px;border-radius:4px;display:grid;place-items:center;font-size:1.5rem;margin-bottom:16px;color:#fff}\n.feat:nth-child(1) .ic{background:linear-gradient(135deg,var(--blue),var(--blue-soft))}\n.feat:nth-child(2) .ic{background:linear-gradient(135deg,var(--gold),var(--amber))}\n.feat:nth-child(3) .ic{background:linear-gradient(135deg,var(--coral),var(--coral-deep))}\n.feat:nth-child(4) .ic{background:linear-gradient(135deg,var(--olive),#5e6a48)}\n.feat:nth-child(5) .ic{background:linear-gradient(135deg,#7a8a3c,#5e6a48)}\n.feat:nth-child(6) .ic{background:linear-gradient(135deg,var(--amber),var(--coral))}\n.feat h3{font-family:var(--display);font-size:1.25rem;font-weight:600;margin-bottom:8px;color:var(--olive-dark)}\n.feat p{font-size:.93rem;color:#5a5c4e;font-weight:300}\n\n/* \u2500\u2500 VOUCHER VALUE \u2500\u2500 */\n.value{background:var(--olive);color:var(--cream);overflow:hidden;position:relative}\n.value::before{content:\"\";position:absolute;inset:0;background:radial-gradient(circle at 78% 20%,rgba(224,112,60,.24),transparent 46%)}\n.value .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1.05fr .95fr;gap:56px;align-items:center}\n.value h2{color:#fff}\n.value .lead{color:rgba(255,255,255,.85)}\n.value ul{list-style:none;margin-top:24px;display:grid;gap:12px}\n.value li{display:flex;align-items:center;gap:13px;font-weight:400;font-size:1.02rem;color:#fff}\n.value .ck{flex:none;width:28px;height:28px;border-radius:4px;display:grid;place-items:center;font-size:.82rem;color:#fff;background:linear-gradient(135deg,var(--gold),var(--coral))}\n.price-card{background:linear-gradient(150deg,#fff,#fff8ee);border-radius:4px;padding:40px 34px;text-align:center;color:var(--ink);box-shadow:0 30px 65px rgba(0,0,0,.4);position:relative;overflow:hidden}\n.price-card .ribbon{position:absolute;top:18px;right:-42px;background:var(--coral);color:#fff;font-weight:700;font-size:.64rem;letter-spacing:.14em;text-transform:uppercase;padding:6px 52px;transform:rotate(45deg)}\n.price-card .once{font-weight:700;font-size:.68rem;letter-spacing:.18em;text-transform:uppercase;color:var(--coral-deep)}\n.price-card .amt{font-family:var(--display);font-weight:600;font-size:4.8rem;line-height:1;color:var(--olive-dark);margin:6px 0}\n.price-card .amt span{font-size:1.6rem;vertical-align:super;font-weight:400}\n.price-card .sub{font-size:.93rem;color:#5a5c4e;margin-bottom:8px;font-weight:300}\n.value-bar{margin:20px 0 8px;background:var(--sage-soft);padding:16px;border-radius:4px}\n.value-bar .vt{font-family:var(--display);font-weight:600;font-size:1.1rem;color:var(--olive-dark)}\n.value-bar .vs{font-size:.84rem;color:var(--olive);margin-top:3px;font-weight:300}\n.price-card .btn-price{\n  display:block;width:100%;margin-top:18px;\n  background:var(--olive);color:#fff;\n  padding:16px;\n  font-family:var(--body);font-weight:700;font-size:.74rem;\n  letter-spacing:.16em;text-transform:uppercase;\n  transition:background .2s;text-align:center;\n}\n.price-card .btn-price:hover{background:var(--olive-dark)}\n.price-card .tiny{font-size:.76rem;color:#7a7c6c;margin-top:14px;font-weight:300}\n\n/* \u2500\u2500 TASTE \u2500\u2500 */\n.taste{background:var(--paper)}\n.site-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(255px,1fr));gap:20px;margin-top:48px}\n.site-card{position:relative;border-radius:4px;overflow:hidden;padding:26px 24px 24px;background:var(--cream);border:1px solid rgba(74,82,52,.1);display:flex;flex-direction:column;min-height:225px;transition:transform .3s,box-shadow .3s}\n.site-card::before{content:\"\";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--accent)}\n.site-card:hover{transform:translateY(-5px);box-shadow:0 18px 40px var(--shadow)}\n.site-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}\n.site-emoji{width:52px;height:52px;border-radius:4px;display:grid;place-items:center;font-size:1.5rem;background:color-mix(in srgb,var(--accent) 14%,white)}\n.site-year{font-family:var(--display);font-weight:600;font-size:1.05rem;color:var(--accent)}\n.site-card h3{font-family:var(--display);font-size:1.28rem;font-weight:600;color:var(--olive-dark);line-height:1.1;margin-bottom:8px}\n.site-card p{font-size:.91rem;color:#5a5c4e;flex:1;font-weight:300;line-height:1.7}\n.site-badge{align-self:flex-start;margin-top:14px;font-size:.66rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;padding:5px 11px;border-radius:30px;background:color-mix(in srgb,var(--accent) 12%,white);color:var(--accent)}\n\n/* \u2500\u2500 INSTALL \u2500\u2500 */\n.install{background:var(--olive);color:var(--cream);overflow:hidden;position:relative}\n.install::before{content:\"\";position:absolute;inset:0;background:radial-gradient(circle at 80% 18%,rgba(200,160,82,.14),transparent 44%)}\n.install .wrap{position:relative;z-index:2;display:grid;grid-template-columns:1.2fr .9fr;gap:60px;align-items:center}\n.install h2{color:#fff}.install .lead{color:rgba(255,255,255,.82)}\n.steps{margin-top:36px;display:flex;flex-direction:column;gap:22px}\n.step{display:flex;gap:18px;align-items:flex-start}\n.step .num{flex:none;width:44px;height:44px;border:2px solid var(--gold);color:var(--gold);font-family:var(--display);font-weight:600;font-size:1.2rem;display:grid;place-items:center}\n.step h4{font-family:var(--display);font-size:1.18rem;font-weight:600;color:#fff;margin-bottom:3px}\n.step p{color:rgba(255,255,255,.78);font-size:.93rem;font-weight:300}\n.qr-card{background:#fff;padding:32px;text-align:center;color:var(--ink);box-shadow:0 30px 60px rgba(0,0,0,.35)}\n.qr-card img{width:188px;height:188px;margin:0 auto 18px}\n.qr-card .qr-title{font-family:var(--display);font-weight:600;font-size:1.2rem;color:var(--olive-dark)}\n.qr-card .qr-sub{font-size:.88rem;color:#5a5c4e;margin-top:6px;font-weight:300}\n.qr-card .url{display:inline-block;margin-top:16px;font-weight:700;color:var(--coral-deep);font-size:.92rem}\n.free-pill{display:inline-block;margin-bottom:14px;background:var(--sage-soft);color:var(--olive);font-weight:700;font-size:.68rem;letter-spacing:.12em;text-transform:uppercase;padding:5px 13px}\n\n/* \u2500\u2500 PARTNER \u2500\u2500 */\n.partner{background:linear-gradient(160deg,#34406a,var(--blue));color:var(--cream);position:relative;overflow:hidden}\n.partner::before{content:\"\";position:absolute;inset:0;background:radial-gradient(circle at 85% 28%,rgba(224,112,60,.22),transparent 48%)}\n.partner .wrap{position:relative;z-index:2;text-align:center;display:flex;flex-direction:column;align-items:center}\n.partner h2{color:#fff;max-width:780px}\n.partner .lead{color:rgba(255,255,255,.85);margin-left:auto;margin-right:auto}\n.partner-perks{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:18px;margin:44px 0;width:100%;max-width:900px}\n.perk{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16);padding:26px 22px;text-align:left;transition:background .3s,transform .3s}\n.perk:hover{background:rgba(255,255,255,.14);transform:translateY(-4px)}\n.perk .pic{font-size:1.5rem;margin-bottom:12px}\n.perk h4{font-family:var(--display);font-size:1.1rem;font-weight:600;color:#fff;margin-bottom:6px}\n.perk p{font-size:.9rem;color:rgba(255,255,255,.8);font-weight:300}\n.btn-partner{\n  display:inline-block;margin-top:8px;\n  background:rgba(255,255,255,.12);color:#fff;\n  border:1.5px solid rgba(255,255,255,.5);\n  padding:16px 44px;\n  font-family:var(--body);font-weight:700;font-size:.76rem;\n  letter-spacing:.18em;text-transform:uppercase;\n  transition:.2s;\n}\n.btn-partner:hover{background:rgba(255,255,255,.2);border-color:#fff}\n\n/* \u2500\u2500 FOOTER (matches CHA site) \u2500\u2500 */\n.cha-footer{\n  background:var(--olive);color:#fff;\n  padding:clamp(52px,8vw,80px) clamp(20px,5vw,60px) 28px;\n  text-align:center;position:relative;overflow:hidden;\n}\n.cha-footer-contact{font-family:var(--display);font-size:2.4rem;font-weight:400;margin-bottom:10px}\n.cha-footer-email{font-size:.92rem;letter-spacing:.04em;margin-bottom:28px;opacity:.9}\n.cha-footer-social{display:flex;gap:14px;justify-content:center;margin-bottom:44px}\n.cha-footer-social a{\n  width:44px;height:44px;border-radius:50%;\n  border:1.5px solid rgba(255,255,255,.55);\n  display:grid;place-items:center;font-size:.88rem;\n  transition:.2s;\n}\n.cha-footer-social a:hover{border-color:#fff;background:rgba(255,255,255,.12)}\n.cha-footer-copy{\n  border-top:1px solid rgba(255,255,255,.18);padding-top:22px;\n  display:flex;flex-wrap:wrap;gap:8px;justify-content:space-between;\n  font-size:.68rem;letter-spacing:.12em;text-transform:uppercase;\n  color:rgba(255,255,255,.7);\n}\n\n/* \u2500\u2500 RESPONSIVE \u2500\u2500 */\n@media(max-width:900px){\n  .cha-nav-links,.cha-social{\n    position:fixed;inset:0 0 0 auto;width:min(78vw,300px);\n    background:var(--olive-dark);flex-direction:column;justify-content:center;gap:24px;\n    padding:48px 36px;transform:translateX(100%);transition:transform .35s;\n    box-shadow:-20px 0 48px rgba(0,0,0,.3);\n  }\n  .cha-nav-links{z-index:2}.cha-social{display:none}\n  .cha-nav-links.open{transform:translateX(0)}\n  .cha-nav-links a{font-size:1.3rem}\n  .cha-dropdown{position:static;display:none!important;background:transparent;box-shadow:none}\n  .burger{display:flex;z-index:1001}\n  .burger.open span:nth-child(1){transform:translateY(7px) rotate(45deg)}\n  .burger.open span:nth-child(2){opacity:0}\n  .burger.open span:nth-child(3){transform:translateY(-7px) rotate(-45deg)}\n  .value .wrap,.install .wrap{grid-template-columns:1fr;gap:44px}\n  .qr-card,.price-card{max-width:360px;margin:0 auto}\n  .flow{grid-template-columns:1fr;gap:36px}\n  .fstep:not(:last-child)::after{content:\"\u2193\";right:auto;left:50%;transform:translateX(-50%);top:auto;bottom:-26px}\n}\n@media(max-width:560px){\n  .hero-stats{gap:18px}.hero-stats b{font-size:1.5rem}\n  .cta-row{flex-direction:column}\n  .btn-cha,.btn-cha-ghost{width:100%;text-align:center;display:block}\n  .countdown div{min-width:50px;padding:7px 8px}\n  .cha-logo{height:42px}.cha-footer-copy{flex-direction:column;text-align:center;gap:6px}\n}\n@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}.reveal{opacity:1;transform:none}.fade-up{opacity:1;transform:none}}\n</style>\n</head>\n<body>\n\n<!-- NAV -->\n<header class=\"cha-nav\">\n  <div class=\"cha-nav-inner\">\n    <a class=\"cha-brand\" href=\"https://clarensheritage.org/\">\n      <img src=\"data:image/png;base64,\" alt=\"Clarens Heritage Association\" class=\"cha-logo\">\n    </a>\n    <ul class=\"cha-nav-links\" id=\"navLinks\">\n      <li><a href=\"https://clarensheritage.org/\">Home</a></li>\n      <li class=\"has-dd\">\n        <a href=\"#\">Menu <span class=\"arrow\">\u25be</span></a>\n        <ul class=\"cha-dropdown\">\n          <li><a href=\"https://clarensheritage.org/blueplaques/\">Blue Plaques</a></li>\n          <li><a href=\"https://clarensheritage.org/buildings/\">Buildings</a></li>\n          <li><a href=\"https://clarensheritage.org/culture/\">Culture</a></li>\n          <li><a href=\"https://clarensheritage.org/farms/\">Farms</a></li>\n          <li><a href=\"https://clarensheritage.org/history/\">History</a></li>\n          <li><a href=\"https://clarensheritage.org/nature/\">Nature</a></li>\n          <li><a href=\"https://clarensheritage.org/people/\">People</a></li>\n        </ul>\n      </li>\n      <li><a href=\"#\" class=\"active\">Heritage Trail</a></li>\n      <li><a href=\"https://clarensheritage.org/events/\">Events</a></li>\n      <li><a href=\"https://clarensheritage.org/contact/\">Contact</a></li>\n    </ul>\n    <div class=\"cha-social\">\n      <a href=\"https://www.facebook.com/profile.php?id=61556962693803\" aria-label=\"Facebook\">f</a>\n      <a href=\"https://www.instagram.com/clarensheritage/\" aria-label=\"Instagram\">\u25ce</a>\n    </div>\n    <button class=\"burger\" id=\"burger\" aria-label=\"Menu\"><span></span><span></span><span></span></button>\n  </div>\n</header>\n\n<!-- HERO -->\n<section class=\"hero\">\n  <img class=\"hero-photo\" src=\"data:image/jpeg;base64,\" alt=\"Panoramic view over Clarens nestled in the Maluti foothills\">\n  <div class=\"hero-scrim\"></div>\n  <div class=\"hero-inner\">\n    <div class=\"countdown-wrap fade-up d1\">\n      <span class=\"launch-pill\" id=\"launchPill\">\u2726 Launching 19 June 2026</span>\n      <div class=\"countdown\" id=\"cd\">\n        <div><b id=\"cdD\">--</b><span>days</span></div>\n        <div><b id=\"cdH\">--</b><span>hrs</span></div>\n        <div><b id=\"cdM\">--</b><span>min</span></div>\n        <div><b id=\"cdS\">--</b><span>sec</span></div>\n      </div>\n    </div>\n    <div class=\"hero-badge fade-up d2\">Clarens Heritage Association \u00b7 Heritage Trail App</div>\n    <h1 class=\"hero-title fade-up d3\">Clarens<br>Heritage Trail</h1>\n    <p class=\"hero-sub fade-up d4\">The whole village in your pocket \u2014 32+ heritage sites, a digital passport, and <b>exclusive vouchers worth more than the app costs.</b></p>\n    <div class=\"hero-stats fade-up d4\">\n      <div><b>32+</b><span>Heritage Sites</span></div>\n      <div><b>5</b><span>Free to explore</span></div>\n      <div><b>R99</b><span>Unlocks everything</span></div>\n    </div>\n    <div class=\"cta-row fade-up d5\">\n      <a class=\"btn-cha\" id=\"getAppBtn\" href=\"https://trail.clarensheritage.org\">Get the App \u2014 Try 5 Sites Free</a>\n      <a class=\"btn-cha-ghost\" href=\"https://clarensheritage.org/partner-programme/\">For Businesses \u2192</a>\n    </div>\n  </div>\n  <div class=\"credit\">Photo: Jan Giebelmann \u00b7 <a href=\"https://commons.wikimedia.org/w/index.php?curid=38877642\" target=\"_blank\" rel=\"noopener\">CC BY-SA 4.0</a></div>\n  <div class=\"scroll-hint\">Explore<span>\u2193</span></div>\n</section>\n\n<!-- MODEL -->\n<section class=\"model\" id=\"how\">\n  <div class=\"wrap center\">\n    <div class=\"reveal\">\n      <span class=\"tag tag-gold\">How it works</span>\n      <h2>Start free. Then <em>unlock everything.</em></h2>\n      <p class=\"lead\">Install the app in seconds \u2014 no App Store, no account. Explore five sites for free, then unlock the full trail and your vouchers for a single R99.</p>\n    </div>\n    <div class=\"flow\">\n      <div class=\"fstep reveal s1\"><div class=\"circle\">\ud83d\udcf2</div><h3>Install in seconds</h3><p>A Progressive Web App \u2014 adds to your home screen straight from your browser.</p><span class=\"badge\">No App Store</span></div>\n      <div class=\"fstep reveal s2\"><div class=\"circle\">\ud83e\udded</div><h3>Explore 5 sites free</h3><p>Walk five Blue Plaque sites and experience the trail before paying a cent.</p><span class=\"badge\">Free to try</span></div>\n      <div class=\"fstep reveal s3\"><div class=\"circle\">\ud83d\udd13</div><h3>Unlock all 32+ for R99</h3><p>One payment opens every site, both trails \u2014 and your partner vouchers.</p><span class=\"badge\">R99 once-off</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- FEATURES -->\n<section class=\"features\" id=\"trail\">\n  <div class=\"wrap\">\n    <div class=\"reveal\">\n      <span class=\"tag tag-coral\">What's inside</span>\n      <h2>Clarens, deeper than a <em>tour guide</em></h2>\n      <p class=\"lead\">Every site tells a real story \u2014 researched by the Clarens Heritage Association, presented with authentic photographs and quick facts.</p>\n    </div>\n    <div class=\"feat-grid\">\n      <div class=\"feat reveal s1\"><div class=\"ic\">\ud83c\udfdb\ufe0f</div><h3>32+ Heritage Sites</h3><p>Full histories, photos and quick facts across two walking trails through the village.</p></div>\n      <div class=\"feat reveal s2\"><div class=\"ic\">\ud83c\udf9f\ufe0f</div><h3>Partner Vouchers</h3><p>Exclusive discounts at Clarens restaurants, caf\u00e9s, galleries and shops.</p></div>\n      <div class=\"feat reveal s3\"><div class=\"ic\">\ud83d\udcd6</div><h3>Digital Passport</h3><p>Collect a stamp at each site you visit and build your own keepsake record.</p></div>\n      <div class=\"feat reveal s4\"><div class=\"ic\">\ud83d\uddfa\ufe0f</div><h3>Interactive Map</h3><p>Live location \u2014 one tap to navigate to any site from where you stand.</p></div>\n      <div class=\"feat reveal s1\"><div class=\"ic\">\ud83d\udcf5</div><h3>Works Offline</h3><p>Fully functional without internet \u2014 ideal for the Free State's mountain signal.</p></div>\n      <div class=\"feat reveal s2\"><div class=\"ic\">\ud83c\udfa7</div><h3>Audio Guides</h3><p>Narrated stories at each stop \u2014 rolling out across the trail after launch.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- VOUCHER VALUE -->\n<section class=\"value\" id=\"value\">\n  <div class=\"wrap\">\n    <div class=\"reveal\">\n      <span class=\"tag\" style=\"background:rgba(255,255,255,.15);color:#ffe1a8\">The real value</span>\n      <h2>An app that <em>pays for itself</em></h2>\n      <p class=\"lead\">R99 doesn't just unlock the history \u2014 it unlocks exclusive vouchers at Clarens businesses. The discounts can cover the cost before you finish your first coffee.</p>\n      <ul>\n        <li class=\"reveal s1\"><span class=\"ck\">\u2713</span> Exclusive partner discounts you won't find anywhere else</li>\n        <li class=\"reveal s2\"><span class=\"ck\">\u2713</span> All 32+ heritage sites &amp; both walking trails</li>\n        <li class=\"reveal s3\"><span class=\"ck\">\u2713</span> Digital passport, interactive map &amp; offline access</li>\n        <li class=\"reveal s4\"><span class=\"ck\">\u2713</span> A share of every R99 funds CHA conservation work</li>\n      </ul>\n    </div>\n    <div class=\"price-card reveal s2\">\n      <span class=\"ribbon\">Full access</span>\n      <div class=\"once\">Once-off payment</div>\n      <div class=\"amt\"><span>R</span>99</div>\n      <div class=\"sub\">Unlocks the entire Heritage Trail \u2014 forever.</div>\n      <div class=\"value-bar\">\n        <div class=\"vt\">\ud83c\udf9f\ufe0f Vouchers worth more than you pay</div>\n        <div class=\"vs\">Spend once on the app, get it back at the till.</div>\n      </div>\n      <a class=\"btn-price\" id=\"getAppBtn2\" href=\"https://trail.clarensheritage.org\">Get the App</a>\n      <div class=\"tiny\">Try 5 sites free first \u00b7 No App Store needed</div>\n    </div>\n  </div>\n</section>\n\n<!-- TASTE -->\n<section class=\"taste\">\n  <div class=\"wrap\">\n    <div class=\"reveal\">\n      <span class=\"tag tag-coral\">A taste of the trail</span>\n      <h2>Stories worth <em>walking for</em></h2>\n      <p class=\"lead\">From a schoolhouse built by ox-wagon to a hill where 4,000 men surrendered \u2014 a glimpse of what waits on the route.</p>\n    </div>\n    <div class=\"site-grid\">\n      <article class=\"site-card reveal s1\" style=\"--accent:#1a4a7a\"><div class=\"site-top\"><div class=\"site-emoji\">\ud83c\udfeb</div><div class=\"site-year\">1914</div></div><h3>Clarens Primary School</h3><p>A sandstone school built by the townspeople \u2014 opened with 42 pupils. Now serves over 1,000 learners.</p><span class=\"site-badge\">Free \u00b7 Blue Plaque</span></article>\n      <article class=\"site-card reveal s2\" style=\"--accent:#4a5234\"><div class=\"site-top\"><div class=\"site-emoji\">\ud83c\udfe0</div><div class=\"site-year\">1920s</div></div><h3>Frost House</h3><p>One of just two corrugated-iron buildings still standing in Clarens \u2014 rescued from ruin and restored in 2015.</p><span class=\"site-badge\">Free \u00b7 Blue Plaque</span></article>\n      <article class=\"site-card reveal s3\" style=\"--accent:#606e42\"><div class=\"site-top\"><div class=\"site-emoji\">\u26ea</div><div class=\"site-year\">1936</div></div><h3>Methodist Church</h3><p>Built by hand \u2014 Hugo Walker lost three fingers crafting its pews, beams and pulpit.</p><span class=\"site-badge\">Free \u00b7 Blue Plaque</span></article>\n      <article class=\"site-card reveal s4\" style=\"--accent:#c8a052\"><div class=\"site-top\"><div class=\"site-emoji\">\ud83e\udea8</div><div class=\"site-year\">1912</div></div><h3>Titanic Rock</h3><p>Named the same year the Titanic sank \u2014 also the year Clarens was founded.</p><span class=\"site-badge\">Natural Heritage</span></article>\n      <article class=\"site-card reveal s1\" style=\"--accent:#8a5a3c\"><div class=\"site-top\"><div class=\"site-emoji\">\ud83c\udff4</div><div class=\"site-year\">1900</div></div><h3>Surrender Hill</h3><p>The largest single Boer surrender of the Anglo-Boer War \u2014 4,314 men laid down their arms here.</p><span class=\"site-badge\">National Monument</span></article>\n      <article class=\"site-card reveal s2\" style=\"--accent:#1a4a7a\"><div class=\"site-top\"><div class=\"site-emoji\">\u26ea</div><div class=\"site-year\">1942</div></div><h3>NG Kerk Clarens</h3><p>The sandstone anchor of the town square \u2014 and the winter night that inspired one of the village's finest buildings.</p><span class=\"site-badge\">Free \u00b7 National Monument</span></article>\n    </div>\n  </div>\n</section>\n\n<!-- INSTALL -->\n<section class=\"install\" id=\"get\">\n  <div class=\"wrap\">\n    <div class=\"reveal\">\n      <span class=\"tag\" style=\"background:rgba(255,255,255,.15);color:#ffe1a8\">Install in 3 steps</span>\n      <h2>No App Store. <em>No waiting.</em></h2>\n      <p class=\"lead\">The Heritage Trail installs directly from your browser in seconds \u2014 and the first five sites are free to explore.</p>\n      <div class=\"steps\">\n        <div class=\"step reveal s1\"><div class=\"num\">1</div><div><h4>Open Chrome or Safari</h4><p>Go to trail.clarensheritage.org on your phone \u2014 or scan the QR code.</p></div></div>\n        <div class=\"step reveal s2\"><div class=\"num\">2</div><div><h4>Tap the menu</h4><p>Android: tap \u22ee (three dots). iPhone: tap the Share button at the bottom.</p></div></div>\n        <div class=\"step reveal s3\"><div class=\"num\">3</div><div><h4>Add to Home Screen</h4><p>The app installs instantly. Explore five sites free, then unlock all 32+ for R99.</p></div></div>\n      </div>\n    </div>\n    <div class=\"qr-card reveal s2\">\n      <span class=\"free-pill\">Scan to install</span>\n      <img src=\"https://api.qrserver.com/v1/create-qr-code/?size=220x220&color=3a4028&bgcolor=ffffff&data=https://trail.clarensheritage.org\" alt=\"QR code\" loading=\"lazy\">\n      <div class=\"qr-title\">Point &amp; install</div>\n      <div class=\"qr-sub\">Aim your camera at the code to open the app \u2014 no typing required.</div>\n      <a class=\"url\" href=\"https://trail.clarensheritage.org\">trail.clarensheritage.org</a>\n    </div>\n  </div>\n</section>\n\n<!-- PARTNER -->\n<section class=\"partner\">\n  <div class=\"wrap\">\n    <div class=\"reveal\">\n      <span class=\"tag\" style=\"background:rgba(255,255,255,.15);color:#ffe1a8\">For Clarens businesses</span>\n      <h2>Be the voucher that <em>brings them in</em></h2>\n      <p class=\"lead\">Vouchers are the heart of the Heritage Trail \u2014 putting your business in front of every visitor who unlocks the app. Free to join, no commission.</p>\n    </div>\n    <div class=\"partner-perks\">\n      <div class=\"perk reveal s1\"><div class=\"pic\">\ud83c\udf9f\ufe0f</div><h4>Free to join</h4><p>No sign-up fee, no monthly cost, no commission \u2014 ever.</p></div>\n      <div class=\"perk reveal s2\"><div class=\"pic\">\ud83d\udc63</div><h4>Drive foot traffic</h4><p>Your exclusive voucher turns trail walkers into paying customers.</p></div>\n      <div class=\"perk reveal s3\"><div class=\"pic\">\ud83d\udccd</div><h4>Featured in the app</h4><p>Shown on the map to every visitor exploring the village.</p></div>\n      <div class=\"perk reveal s4\"><div class=\"pic\">\ud83c\udf3f</div><h4>Support heritage</h4><p>Part of a community project conserving and celebrating Clarens.</p></div>\n    </div>\n    <a class=\"btn-partner reveal s2\" href=\"https://clarensheritage.org/partner-programme/\">See the benefits &amp; apply \u2192</a>\n  </div>\n</section>\n\n<!-- FOOTER (matches CHA site) -->\n<footer class=\"cha-footer\">\n  <div class=\"cha-footer-contact\">Contact</div>\n  <div class=\"cha-footer-email\">info@clarensheritage.org</div>\n  <div class=\"cha-footer-social\">\n    <a href=\"https://www.facebook.com/profile.php?id=61556962693803\" aria-label=\"Facebook\">f</a>\n    <a href=\"https://www.instagram.com/clarensheritage/\" aria-label=\"Instagram\">\u25ce</a>\n  </div>\n  <div class=\"cha-footer-copy\">\n    <span>Clarens Heritage Association 2024 \u00a9 All Rights Reserved</span>\n    <span>Website by <a href=\"http://www.themakery.co\" style=\"color:inherit;text-decoration:underline\">The Makery Co.</a></span>\n  </div>\n</footer>\n\n<script>\nvar burger=document.getElementById('burger'),nav=document.getElementById('navLinks');\nburger.addEventListener('click',function(){burger.classList.toggle('open');nav.classList.toggle('open');});\nnav.querySelectorAll('a').forEach(function(a){a.addEventListener('click',function(){if(window.innerWidth<900){burger.classList.remove('open');nav.classList.remove('open');}});});\n\nvar io=new IntersectionObserver(function(entries){\n  entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});\n},{threshold:.15,rootMargin:'0px 0px -40px 0px'});\ndocument.querySelectorAll('.reveal').forEach(function(el){io.observe(el);});\n\nvar launchTime=new Date('2026-06-19T00:00:00+02:00').getTime();\nvar cd=document.getElementById('cd'),pill=document.getElementById('launchPill');\nvar appBtn=document.getElementById('getAppBtn');\nvar appBtn2=document.getElementById('getAppBtn2');\nvar APP_URL='https://trail.clarensheritage.org';\n\nfunction setAppButtons(live){\n  if(live){\n    appBtn.href=APP_URL;appBtn.textContent='Get the App \\u2014 Try 5 Sites Free';appBtn.classList.remove('btn-locked');\n    if(appBtn2){appBtn2.href=APP_URL;appBtn2.textContent='Get the App';appBtn2.style.opacity='';}\n  } else {\n    appBtn.href='#';appBtn.textContent='Available 19 June 2026';appBtn.classList.add('btn-locked');\n    if(appBtn2){appBtn2.href='#';appBtn2.textContent='Available 19 June 2026';appBtn2.style.cssText='pointer-events:none;opacity:.6';}\n  }\n}\n\nfunction tick(){\n  var diff=launchTime-Date.now();\n  if(diff<=0){\n    cd.style.display='none';pill.textContent='\\u2756 Now live \\u2014 explore Clarens';\n    setAppButtons(true);\n    return;\n  }\n  setAppButtons(false);\n  var d=Math.floor(diff/86400000),h=Math.floor(diff/3600000)%24,m=Math.floor(diff/60000)%60,s=Math.floor(diff/1000)%60;\n  document.getElementById('cdD').textContent=d;\n  document.getElementById('cdH').textContent=('0'+h).slice(-2);\n  document.getElementById('cdM').textContent=('0'+m).slice(-2);\n  document.getElementById('cdS').textContent=('0'+s).slice(-2);\n}\ntick();setInterval(tick,1000);\n</script>\n</body>\n</html>\n";
const PARTNER_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Business Partner Programme \u2014 Clarens Heritage Trail</title>\n<meta name=\"description\" content=\"Join the Clarens Heritage Trail Business Partner Programme. Reach every heritage visitor, offer an exclusive voucher, and support local heritage conservation. Free to join, no commission.\">\n<link rel=\"icon\" href=\"https://clarensheritage.org/wp-content/uploads/2024/10/cropped-Favicon-1-270x270.jpg\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,400;0,600;0,700;1,400&family=Lato:wght@300;400;700&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --olive:#4a5234;--olive-dark:#3a4028;--olive-deep:#2b3022;\n  --sage:#c8d4b8;--sage-soft:#dde6cf;--cream:#faf4e8;--sand:#f0e3cd;\n  --gold:#c8a052;--amber:#e0a23f;--coral:#e0703c;--coral-deep:#c2542a;\n  --blue:#1a4a7a;--blue-soft:#3d6fa0;--ink:#2b2a26;--paper:#fffdf8;\n  --shadow:rgba(74,82,52,.18);\n  --display:'Cormorant Garamond',Georgia,serif;\n  --body:'Lato',-apple-system,system-ui,sans-serif;\n}\n*{margin:0;padding:0;box-sizing:border-box}\nhtml{scroll-behavior:smooth;-webkit-text-size-adjust:100%}\nbody{font-family:var(--body);color:var(--ink);background:var(--cream);line-height:1.7;overflow-x:hidden}\nimg{max-width:100%;display:block}\na{color:inherit;text-decoration:none}\n\n/* NAV */\n.cha-nav{position:fixed;top:0;left:0;right:0;z-index:1000;background:var(--olive)}\n.cha-nav-inner{max-width:1440px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;padding:16px clamp(20px,5vw,60px)}\n.cha-brand{display:flex;align-items:center}\n.cha-logo{height:54px;width:auto;filter:brightness(0) invert(1)}\n.cha-nav-links{list-style:none;display:flex;align-items:center;gap:28px}\n.cha-nav-links>li{position:relative}\n.cha-nav-links a{color:rgba(255,255,255,.88);font-family:var(--display);font-size:1.02rem;letter-spacing:.04em;transition:color .2s;white-space:nowrap}\n.cha-nav-links a:hover,.cha-nav-links a.active{color:#fff}\n.arrow{font-size:.7rem;margin-left:3px}\n.cha-dropdown{position:absolute;top:calc(100% + 12px);left:0;background:var(--olive);min-width:164px;display:none;box-shadow:0 10px 28px rgba(0,0,0,.25);border-top:2px solid rgba(255,255,255,.15)}\n.cha-nav-links li:hover .cha-dropdown{display:block}\n.cha-dropdown li a{display:block;padding:10px 20px;font-size:.96rem}\n.cha-social{display:flex;gap:8px;margin-left:14px}\n.cha-social a{color:#fff;width:30px;height:30px;border-radius:50%;border:1.5px solid rgba(255,255,255,.55);display:grid;place-items:center;font-size:.8rem;transition:.2s}\n.cha-social a:hover{border-color:#fff;background:rgba(255,255,255,.12)}\n.burger{display:none;flex-direction:column;gap:5px;cursor:pointer;padding:6px;background:none;border:0;margin-left:10px}\n.burger span{width:26px;height:2px;background:#fff;border-radius:1px;transition:.3s}\n\n/* HERO */\n.phero{background:var(--olive);padding:clamp(130px,20vh,180px) clamp(20px,6vw,64px) clamp(70px,10vh,110px);overflow:hidden;position:relative}\n.phero::before{content:\"\";position:absolute;inset:0;background:radial-gradient(circle at 80% 25%,rgba(224,112,60,.22),transparent 46%),radial-gradient(circle at 8% 85%,rgba(200,160,82,.16),transparent 40%)}\n.phero-inner{position:relative;z-index:2;max-width:820px;margin:0 auto;text-align:center;color:#fff}\n.hero-badge{display:inline-block;border:1.5px solid rgba(255,255,255,.5);color:rgba(255,255,255,.85);font-family:var(--body);font-weight:700;font-size:.7rem;letter-spacing:.18em;text-transform:uppercase;padding:7px 18px;border-radius:40px;margin-bottom:22px}\n.phero h1{font-family:var(--display);font-weight:400;font-size:clamp(2.4rem,7vw,4.8rem);line-height:1.05;letter-spacing:.01em;text-shadow:0 4px 24px rgba(0,0,0,.2)}\n.phero h1 em{font-style:italic}\n.phero p{font-size:clamp(1rem,2.2vw,1.3rem);color:rgba(255,255,255,.9);max-width:620px;margin:20px auto 30px;font-weight:300;line-height:1.8}\n.btn-cha{display:inline-block;background:#fff;color:var(--olive-dark);padding:16px 44px;font-family:var(--body);font-weight:700;font-size:.76rem;letter-spacing:.18em;text-transform:uppercase;transition:.2s}\n.btn-cha:hover{background:rgba(255,255,255,.9);transform:translateY(-2px)}\n.free-chips{display:flex;flex-wrap:wrap;gap:12px;justify-content:center;margin-top:28px}\n.chip{background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.22);padding:8px 16px;font-weight:600;font-size:.84rem;color:#fff;letter-spacing:.04em}\n.chip b{font-weight:700}\n\n/* SECTIONS */\nsection{position:relative}\n.wrap{max-width:1080px;margin:0 auto;padding:clamp(58px,9vw,108px) clamp(20px,6vw,64px)}\n.tag{display:inline-block;font-weight:700;font-size:.68rem;letter-spacing:.18em;text-transform:uppercase;padding:7px 15px;border-radius:40px;margin-bottom:16px}\n.tag-gold{background:rgba(200,160,82,.18);color:#9c7420}\n.tag-coral{background:rgba(224,112,60,.16);color:var(--coral-deep)}\n.tag-blue{background:rgba(26,74,122,.12);color:var(--blue)}\nh2{font-family:var(--display);font-weight:400;font-size:clamp(1.9rem,4.5vw,3rem);line-height:1.1;letter-spacing:.01em;color:var(--olive-dark)}\nh2 em{font-style:italic;color:var(--coral-deep)}\n.lead{font-size:clamp(1rem,2vw,1.18rem);color:#5a5c4e;max-width:640px;margin-top:14px;font-weight:300;line-height:1.8}\n.center{text-align:center}.center .lead{margin-left:auto;margin-right:auto}\n\n/* BENEFITS */\n.benefits{background:var(--paper)}\n.b-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(248px,1fr));gap:22px;margin-top:46px}\n.bcard{padding:32px 26px;background:var(--cream);border:1px solid rgba(74,82,52,.09);transition:transform .3s,box-shadow .3s}\n.bcard:hover{transform:translateY(-6px);box-shadow:0 20px 44px var(--shadow)}\n.bcard .ic{width:54px;height:54px;display:grid;place-items:center;font-size:1.5rem;color:#fff;margin-bottom:16px}\n.bcard:nth-child(1) .ic{background:linear-gradient(135deg,var(--coral),var(--coral-deep))}\n.bcard:nth-child(2) .ic{background:linear-gradient(135deg,var(--gold),var(--amber))}\n.bcard:nth-child(3) .ic{background:linear-gradient(135deg,var(--blue),var(--blue-soft))}\n.bcard:nth-child(4) .ic{background:linear-gradient(135deg,var(--olive),#5e6a48)}\n.bcard:nth-child(5) .ic{background:linear-gradient(135deg,#7a8a3c,var(--sage))}\n.bcard:nth-child(6) .ic{background:linear-gradient(135deg,var(--amber),var(--coral))}\n.bcard h3{font-family:var(--display);font-size:1.24rem;font-weight:600;color:var(--olive-dark);margin-bottom:8px}\n.bcard p{font-size:.93rem;color:#5a5c4e;font-weight:300}\n\n/* HOW IT WORKS */\n.how{background:linear-gradient(180deg,var(--cream),var(--sand))}\n.stepline{display:grid;grid-template-columns:repeat(auto-fit,minmax(185px,1fr));gap:24px;margin-top:44px}\n.sstep{text-align:center}\n.sstep .num{width:54px;height:54px;border:2px solid var(--gold);color:var(--gold);font-family:var(--display);font-weight:600;font-size:1.4rem;display:grid;place-items:center;margin:0 auto 16px}\n.sstep h4{font-family:var(--display);font-size:1.12rem;font-weight:600;color:var(--olive-dark);margin-bottom:6px}\n.sstep p{color:#5a5c4e;font-size:.92rem;font-weight:300}\n\n/* CONDITIONS */\n.how .sstep h4{color:var(--olive-dark)}.how .sstep p{color:#5a5c4e}\n\n/* SIGNUP */\n.signup{background:var(--olive);color:var(--cream)}\n.signup h2{color:#fff}.signup .lead{color:rgba(255,255,255,.82)}\n.signup .stepline{margin-top:44px}\n.signup .sstep .num{border-color:var(--gold);color:var(--gold)}\n.signup .sstep h4{color:#fff}.signup .sstep p{color:rgba(255,255,255,.78)}\n\n/* FORM */\n.apply{background:var(--paper)}\n.form-card{background:var(--cream);border:1px solid rgba(74,82,52,.1);padding:clamp(26px,5vw,46px);box-shadow:0 22px 52px var(--shadow);margin-top:36px}\n.frow{display:grid;grid-template-columns:1fr 1fr;gap:18px}\n.field{margin-bottom:18px}\n.field label{display:block;font-weight:700;font-size:.82rem;color:var(--olive-dark);margin-bottom:7px;letter-spacing:.02em}\n.field label .req{color:var(--coral-deep)}\n.field input,.field select,.field textarea{width:100%;padding:12px 15px;border:1.5px solid rgba(74,82,52,.2);background:var(--paper);font-family:var(--body);font-size:.97rem;color:var(--ink);transition:border .2s,box-shadow .2s}\n.field input:focus,.field select:focus,.field textarea:focus{outline:none;border-color:var(--gold);box-shadow:0 0 0 3px rgba(200,160,82,.16)}\n.field textarea{resize:vertical;min-height:90px}\n.form-card .btn-submit{\n  display:block;width:100%;margin-top:8px;\n  background:var(--olive);color:#fff;\n  padding:16px;border:0;cursor:pointer;\n  font-family:var(--body);font-weight:700;font-size:.76rem;\n  letter-spacing:.18em;text-transform:uppercase;\n  transition:background .2s;\n}\n.form-card .btn-submit:hover{background:var(--olive-dark)}\n.formnote{font-size:.8rem;color:#7a7c6c;margin-top:14px;text-align:center;font-weight:300}\n.formnote a{color:var(--coral-deep);font-weight:700}\n.thanks{display:none;text-align:center;padding:18px 0}\n.thanks.show{display:block}\n.thanks .big{font-size:2.4rem;margin-bottom:10px}\n.thanks h3{font-family:var(--display);font-size:1.5rem;color:var(--olive-dark);margin-bottom:8px}\n.thanks p{color:#5a5c4e;font-weight:300}\n\n/* FOOTER */\n.cha-footer{background:var(--olive);color:#fff;padding:clamp(52px,8vw,80px) clamp(20px,5vw,60px) 28px;text-align:center}\n.cha-footer-contact{font-family:var(--display);font-size:2.4rem;font-weight:400;margin-bottom:10px}\n.cha-footer-email{font-size:.92rem;letter-spacing:.04em;margin-bottom:28px;opacity:.9}\n.cha-footer-social{display:flex;gap:14px;justify-content:center;margin-bottom:44px}\n.cha-footer-social a{width:44px;height:44px;border-radius:50%;border:1.5px solid rgba(255,255,255,.55);display:grid;place-items:center;font-size:.88rem;transition:.2s}\n.cha-footer-social a:hover{border-color:#fff;background:rgba(255,255,255,.12)}\n.cha-footer-copy{border-top:1px solid rgba(255,255,255,.18);padding-top:22px;display:flex;flex-wrap:wrap;gap:8px;justify-content:space-between;font-size:.68rem;letter-spacing:.12em;text-transform:uppercase;color:rgba(255,255,255,.7)}\n\n/* REVEAL */\n.reveal{opacity:0;transform:translateY(36px);transition:opacity .7s ease,transform .7s cubic-bezier(.2,.8,.2,1)}\n.reveal.in{opacity:1;transform:none}\n.reveal.in.s1{transition-delay:.07s}.reveal.in.s2{transition-delay:.14s}.reveal.in.s3{transition-delay:.21s}.reveal.in.s4{transition-delay:.28s}\n\n@media(max-width:900px){\n  .cha-nav-links,.cha-social{position:fixed;inset:0 0 0 auto;width:min(78vw,300px);background:var(--olive-dark);flex-direction:column;justify-content:center;gap:24px;padding:48px 36px;transform:translateX(100%);transition:transform .35s;box-shadow:-20px 0 48px rgba(0,0,0,.3)}\n  .cha-nav-links{z-index:2}.cha-social{display:none}\n  .cha-nav-links.open{transform:translateX(0)}\n  .cha-nav-links a{font-size:1.3rem}\n  .cha-dropdown{position:static;display:none!important;background:transparent;box-shadow:none}\n  .burger{display:flex;z-index:1001}\n  .burger.open span:nth-child(1){transform:translateY(7px) rotate(45deg)}\n  .burger.open span:nth-child(2){opacity:0}\n  .burger.open span:nth-child(3){transform:translateY(-7px) rotate(-45deg)}\n  .frow{grid-template-columns:1fr}\n  .cha-footer-copy{flex-direction:column;text-align:center;gap:6px}\n}\n@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}.reveal{opacity:1;transform:none}}\n</style>\n</head>\n<body>\n\n<header class=\"cha-nav\">\n  <div class=\"cha-nav-inner\">\n    <a class=\"cha-brand\" href=\"https://clarensheritage.org/\">\n      <img src=\"data:image/png;base64,\" alt=\"Clarens Heritage Association\" class=\"cha-logo\">\n    </a>\n    <ul class=\"cha-nav-links\" id=\"navLinks\">\n      <li><a href=\"https://clarensheritage.org/\">Home</a></li>\n      <li class=\"has-dd\">\n        <a href=\"#\">Menu <span class=\"arrow\">\u25be</span></a>\n        <ul class=\"cha-dropdown\">\n          <li><a href=\"https://clarensheritage.org/blueplaques/\">Blue Plaques</a></li>\n          <li><a href=\"https://clarensheritage.org/buildings/\">Buildings</a></li>\n          <li><a href=\"https://clarensheritage.org/culture/\">Culture</a></li>\n          <li><a href=\"https://clarensheritage.org/farms/\">Farms</a></li>\n          <li><a href=\"https://clarensheritage.org/history/\">History</a></li>\n          <li><a href=\"https://clarensheritage.org/nature/\">Nature</a></li>\n          <li><a href=\"https://clarensheritage.org/people/\">People</a></li>\n        </ul>\n      </li>\n      <li><a href=\"https://clarensheritage.org/trail/\">Heritage Trail</a></li>\n      <li><a href=\"https://clarensheritage.org/events/\">Events</a></li>\n      <li><a href=\"https://clarensheritage.org/contact/\">Contact</a></li>\n    </ul>\n    <div class=\"cha-social\">\n      <a href=\"https://www.facebook.com/profile.php?id=61556962693803\" aria-label=\"Facebook\">f</a>\n      <a href=\"https://www.instagram.com/clarensheritage/\" aria-label=\"Instagram\">\u25ce</a>\n    </div>\n    <button class=\"burger\" id=\"burger\" aria-label=\"Menu\"><span></span><span></span><span></span></button>\n  </div>\n</header>\n\n<section class=\"phero\">\n  <div class=\"phero-inner\">\n    <span class=\"hero-badge\">Clarens Heritage Association \u00b7 Partner Programme</span>\n    <h1>Reach every <em>heritage visitor</em> in Clarens</h1>\n    <p>Put your business in front of every visitor who unlocks the Heritage Trail app \u2014 offer an exclusive voucher, drive foot traffic, and help conserve the village.</p>\n    <a class=\"btn-cha\" href=\"#apply\">Apply to become a partner</a>\n    <div class=\"free-chips\">\n      <span class=\"chip\"><b>Free</b> to join</span>\n      <span class=\"chip\"><b>No</b> commission</span>\n      <span class=\"chip\"><b>No</b> monthly fee</span>\n    </div>\n  </div>\n</section>\n\n<section class=\"benefits\">\n  <div class=\"wrap center\">\n    <div class=\"reveal\">\n      <span class=\"tag tag-coral\">Why partner with us</span>\n      <h2>Visitors with their <em>phones in hand</em></h2>\n      <p class=\"lead\">Trail users are exactly the kind of visitor local businesses want \u2014 curious, present in the village, and actively looking for what to do, eat and buy next.</p>\n    </div>\n    <div class=\"b-grid\" style=\"text-align:left\">\n      <div class=\"bcard reveal s1\"><div class=\"ic\">\ud83c\udf9f\ufe0f</div><h3>Completely free</h3><p>No sign-up fee, no monthly cost and no commission on anything you sell.</p></div>\n      <div class=\"bcard reveal s2\"><div class=\"ic\">\ud83d\udc63</div><h3>Drive foot traffic</h3><p>Your exclusive voucher turns trail walkers into paying customers at your door.</p></div>\n      <div class=\"bcard reveal s3\"><div class=\"ic\">\ud83d\udccd</div><h3>Featured in the app</h3><p>Your business appears on the interactive map, seen by every visitor exploring the village.</p></div>\n      <div class=\"bcard reveal s4\"><div class=\"ic\">\ud83d\udcc8</div><h3>Quality visitors</h3><p>Heritage tourists spend on food, art, coffee and accommodation \u2014 your voucher reaches them at the right moment.</p></div>\n      <div class=\"bcard reveal s1\"><div class=\"ic\">\ud83c\udf3f</div><h3>Support heritage</h3><p>A share of proceeds funds CHA conservation and research work in Clarens.</p></div>\n      <div class=\"bcard reveal s2\"><div class=\"ic\">\u26a1</div><h3>Effortless to run</h3><p>Visitors show the voucher on their phone at your till. Nothing to install, no admin on your side.</p></div>\n    </div>\n  </div>\n</section>\n\n<section class=\"how\" id=\"how\">\n  <div class=\"wrap\">\n    <div class=\"reveal\">\n      <span class=\"tag tag-gold\">How it works</span>\n      <h2>The voucher lives <em>in the app</em></h2>\n      <p class=\"lead\">No QR scanners, no stamp pads, no hardware. The visitor unlocks your voucher inside the app and simply shows the confirmed screen to your team.</p>\n    </div>\n    <div class=\"stepline\">\n      <div class=\"sstep reveal s1\"><div class=\"num\">1</div><h4>Visitor unlocks it</h4><p>Your voucher appears in the app once the visitor meets the conditions you choose.</p></div>\n      <div class=\"sstep reveal s2\"><div class=\"num\">2</div><h4>They show the screen</h4><p>They confirm the voucher and present the screen \u2014 with your business name \u2014 at your till.</p></div>\n      <div class=\"sstep reveal s3\"><div class=\"num\">3</div><h4>You honour the offer</h4><p>Give the discount as described. Each voucher is single-use per visitor.</p></div>\n    </div>\n\n    <div class=\"reveal\" style=\"margin-top:80px\">\n      <span class=\"tag tag-coral\">You're in control</span>\n      <h2>Set your own <em>conditions</em></h2>\n      <p class=\"lead\">Decide exactly who can unlock your voucher. You can combine options, add a date window, or cap the total number available.</p>\n    </div>\n    <div class=\"b-grid\" style=\"text-align:left;margin-top:38px\">\n      <div class=\"bcard reveal s1\"><div class=\"ic\" style=\"background:linear-gradient(135deg,#4a5234,#5e6a48)\">\ud83d\udd13</div><h3>Paid app users only</h3><p>The default. Only visitors who've unlocked the full app (R99) can see and redeem your voucher.</p></div>\n      <div class=\"bcard reveal s2\"><div class=\"ic\" style=\"background:linear-gradient(135deg,#1a4a7a,#3d6fa0)\">\ud83d\udcd6</div><h3>Earned with stamps</h3><p>Require visitors to collect a number of passport stamps first \u2014 rewards those who walk more of the trail.</p></div>\n      <div class=\"bcard reveal s3\"><div class=\"ic\" style=\"background:linear-gradient(135deg,#c8a052,#e0703c)\">\ud83d\udccd</div><h3>Visit a specific site</h3><p>Unlock only after the visitor has been to a particular heritage site \u2014 great for guiding footfall to your area.</p></div>\n    </div>\n    <p class=\"lead\" style=\"margin-top:24px;font-size:.96rem;max-width:700px\">You can also limit a voucher to a date window or cap the total number available \u2014 just tell us on the application form.</p>\n  </div>\n</section>\n\n<section class=\"signup\">\n  <div class=\"wrap center\">\n    <div class=\"reveal\">\n      <span class=\"tag\" style=\"background:rgba(255,255,255,.14);color:#ffe1a8\">Getting started</span>\n      <h2>Live in <em>three easy steps</em></h2>\n    </div>\n    <div class=\"stepline\">\n      <div class=\"sstep reveal s1\"><div class=\"num\">1</div><h4>Apply below</h4><p>Tell us about your business and the voucher you'd like to offer.</p></div>\n      <div class=\"sstep reveal s2\"><div class=\"num\">2</div><h4>We set you up</h4><p>CHA adds your business and voucher to the app, with the conditions you chose.</p></div>\n      <div class=\"sstep reveal s3\"><div class=\"num\">3</div><h4>Welcome visitors</h4><p>Trail users find you in the app and redeem your voucher in-store.</p></div>\n    </div>\n  </div>\n</section>\n\n<section class=\"apply\" id=\"apply\">\n  <div class=\"wrap center\">\n    <div class=\"reveal\">\n      <span class=\"tag tag-coral\">Apply now</span>\n      <h2>Join the <em>partner programme</em></h2>\n      <p class=\"lead\">Fill in the form below \u2014 it takes two minutes. The Clarens Heritage Association will be in touch to get you set up.</p>\n    </div>\n    <div class=\"form-card reveal s1\" style=\"text-align:left\">\n      <form id=\"partnerForm\">\n        <div class=\"frow\">\n          <div class=\"field\"><label>Business name <span class=\"req\">*</span></label><input type=\"text\" name=\"business\" required></div>\n          <div class=\"field\"><label>Business type</label>\n            <select name=\"type\">\n              <option value=\"\">Select\u2026</option>\n              <option>Restaurant / Caf\u00e9</option>\n              <option>Accommodation / Guesthouse</option>\n              <option>Art gallery / Studio</option>\n              <option>Retail / Shop</option>\n              <option>Activity / Tour operator</option>\n              <option>Other</option>\n            </select>\n          </div>\n        </div>\n        <div class=\"frow\">\n          <div class=\"field\"><label>Contact name <span class=\"req\">*</span></label><input type=\"text\" name=\"contact\" required></div>\n          <div class=\"field\"><label>Phone</label><input type=\"tel\" name=\"phone\"></div>\n        </div>\n        <div class=\"field\"><label>Email <span class=\"req\">*</span></label><input type=\"email\" name=\"email\" required></div>\n        <div class=\"field\"><label>Business logo <span class=\"req\">*</span> <span style=\"font-weight:300;color:#7a7c6c\">\u2014 paste a URL, or attach the file to your email (min. 300\u00d7300 px, PNG or WebP)</span></label><input type=\"url\" name=\"logoUrl\" placeholder=\"https://... or attach to email\"></div>\n        <div class=\"field\"><label>Short voucher label <span class=\"req\">*</span> <span style=\"font-weight:300;color:#7a7c6c\">(max 25 chars \u2014 e.g. \"10% Discount\")</span></label><input type=\"text\" name=\"offerLabel\" maxlength=\"25\" required></div>\n        <div class=\"frow\">\n          <div class=\"field\"><label>Offer type</label>\n            <select name=\"offerType\">\n              <option value=\"\">Select\u2026</option>\n              <option>% Discount</option>\n              <option>Fixed amount off</option>\n              <option>Free item</option>\n              <option>Other</option>\n            </select>\n          </div>\n          <div class=\"field\"><label>Exclusions / conditions</label><input type=\"text\" name=\"exclusions\" placeholder='e.g. \"Not valid on alcohol\"'></div>\n        </div>\n        <div class=\"field\"><label>Offer description</label><textarea name=\"offer\" placeholder=\"One sentence \u2014 e.g. 10% off your total bill, valid once per app user\u2026\"></textarea></div>\n        <div class=\"field\"><label>Who should be able to unlock it?</label>\n          <select name=\"condition\">\n            <option value=\"paid\">Paid app users only (default)</option>\n            <option value=\"stamps\">Visitors who've collected a number of stamps</option>\n            <option value=\"site\">Visitors who've visited a specific site</option>\n            <option value=\"combo\">A combination of the above</option>\n          </select>\n        </div>\n        <div class=\"field\"><label>Condition details <span style=\"font-weight:300;color:#7a7c6c\">(if not \"paid only\")</span></label><input type=\"text\" name=\"conditionDetail\" placeholder='e.g. \"5 stamps\" or \"after visiting NG Kerk\"'></div>\n        <div class=\"field\"><label>Limited availability? <span style=\"font-weight:300;color:#7a7c6c\">(optional)</span></label><input type=\"text\" name=\"limits\" placeholder=\"e.g. valid 1\u201331 December, or first 100 vouchers only\"></div>\n        <div class=\"field\"><label>Anything else?</label><textarea name=\"message\"></textarea></div>\n        <button type=\"submit\" class=\"btn-submit\">Submit application</button>\n        <p class=\"formnote\">Prefer email? Write to <a href=\"mailto:info@clarensheritage.org?subject=Heritage%20Trail%20Partner%20Application\">info@clarensheritage.org</a></p>\n      </form>\n      <div class=\"thanks\" id=\"thanks\">\n        <div class=\"big\">\ud83c\udf89</div>\n        <h3>Your email is ready to send</h3>\n        <p>We've opened your email app with the details filled in \u2014 just hit send. Or write directly to <a href=\"mailto:info@clarensheritage.org\" style=\"color:var(--coral-deep);font-weight:700\">info@clarensheritage.org</a>.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<footer class=\"cha-footer\">\n  <div class=\"cha-footer-contact\">Contact</div>\n  <div class=\"cha-footer-email\">info@clarensheritage.org</div>\n  <div class=\"cha-footer-social\">\n    <a href=\"https://www.facebook.com/profile.php?id=61556962693803\" aria-label=\"Facebook\">f</a>\n    <a href=\"https://www.instagram.com/clarensheritage/\" aria-label=\"Instagram\">\u25ce</a>\n  </div>\n  <div class=\"cha-footer-copy\">\n    <span>Clarens Heritage Association 2024 \u00a9 All Rights Reserved</span>\n    <span>Website by <a href=\"http://www.themakery.co\" style=\"color:inherit;text-decoration:underline\">The Makery Co.</a></span>\n  </div>\n</footer>\n\n<script>\nvar burger=document.getElementById('burger'),nav=document.getElementById('navLinks');\nburger.addEventListener('click',function(){burger.classList.toggle('open');nav.classList.toggle('open');});\nnav.querySelectorAll('a').forEach(function(a){a.addEventListener('click',function(){if(window.innerWidth<900){burger.classList.remove('open');nav.classList.remove('open');}});});\n\nvar io=new IntersectionObserver(function(entries){\n  entries.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});\n},{threshold:.15,rootMargin:'0px 0px -40px 0px'});\ndocument.querySelectorAll('.reveal').forEach(function(el){io.observe(el);});\n\nvar form=document.getElementById('partnerForm');\nform.addEventListener('submit',function(ev){\n  ev.preventDefault();\n  var d=new FormData(form);\n  var body=\n    'Business name: '+(d.get('business')||'')+'\\n'+\n    'Business type: '+(d.get('type')||'')+'\\n'+\n    'Contact name: '+(d.get('contact')||'')+'\\n'+\n    'Phone: '+(d.get('phone')||'')+'\\n'+\n    'Email: '+(d.get('email')||'')+'\\n'+\n    'Logo URL: '+(d.get('logoUrl')||'(will attach to email)')+'\\n\\n'+\n    'Voucher label: '+(d.get('offerLabel')||'')+'\\n'+\n    'Offer type: '+(d.get('offerType')||'')+'\\n'+\n    'Offer description: '+(d.get('offer')||'')+'\\n'+\n    'Exclusions: '+(d.get('exclusions')||'')+'\\n\\n'+\n    'Unlock condition: '+(d.get('condition')||'')+'\\n'+\n    'Condition details: '+(d.get('conditionDetail')||'')+'\\n'+\n    'Limited availability: '+(d.get('limits')||'')+'\\n\\n'+\n    'Message:\\n'+(d.get('message')||'');\n  var href='mailto:info@clarensheritage.org'+\n    '?subject='+encodeURIComponent('Heritage Trail Partner Application \u2014 '+(d.get('business')||''))+\n    '&body='+encodeURIComponent(body);\n  window.location.href=href;\n  document.getElementById('thanks').classList.add('show');\n});\n</script>\n</body>\n</html>\n";

addEventListener('fetch', event => {
  event.respondWith(handleRequest(event.request));
});

function handleRequest(request) {
  const url  = new URL(request.url);
  const path = url.pathname.replace(/\/+$/, '') || '/';

  if (path === '/trail' || path === '/trail/') {
    return new Response(TRAIL_HTML, {
      status: 200,
      headers: { 'Content-Type': 'text/html; charset=utf-8' },
    });
  }

  if (path === '/partners' || path === '/partners/') {
    return new Response(PARTNER_HTML, {
      status: 200,
      headers: { 'Content-Type': 'text/html; charset=utf-8' },
    });
  }

  return new Response('Not Found', { status: 404 });
}
